esercizio.consegna:
Modifica lo script `res://ui/dialogue_box.gd` per mostrare le battute di testo una lettera alla volta attraverso un'animazione fluida.

1. Aggiungi la variabile esportata `characters_per_second: float = 30.0` per regolare la velocità di scrittura.
2. Salva il riferimento all'animazione attiva in una variabile `_tween: Tween`.
3. Nella funzione `show_line(speaker: String, text: String)`:
   - reimposta `visible_ratio` del nodo `dialogue_label` a `0.0`;
   - nascondi l'indicatore `continue_indicator`;
   - se c'è un `Tween` già in esecuzione, interrompilo con `kill()`;
   - calcola il numero di caratteri effettivi con `dialogue_label.get_total_character_count()`;
   - calcola la durata dividendo i caratteri per `characters_per_second`;
   - crea un `Tween`, anima `visible_ratio` fino a `1.0` per quella durata e collega il segnale `finished` del tween al metodo `_on_typing_finished`.
4. Crea il metodo `_on_typing_finished() -> void` che rende visibile `continue_indicator`.
5. Nella funzione `clear()`, se `_tween` è in esecuzione, fermalo prima di azzerare i testi.

file.contenuto:
extends PanelContainer

@export var characters_per_second: float = 30.0

var _tween: Tween

@onready var speaker_label: Label = $VBoxContainer/SpeakerLabel
@onready var dialogue_label: RichTextLabel = $VBoxContainer/DialogueLabel
@onready var continue_indicator: Label = $VBoxContainer/ContinueIndicator


func _ready() -> void:
	continue_indicator.visible = false


func show_line(speaker: String, text: String) -> void:
	var clean_speaker := speaker.strip_edges()
	if clean_speaker.is_empty():
		speaker_label.visible = false
	else:
		speaker_label.visible = true
		speaker_label.text = clean_speaker

	dialogue_label.text = text
	dialogue_label.scroll_to_line(0)
	dialogue_label.visible_ratio = 0.0
	set_indicator_visible(false)

	if _tween and _tween.is_running():
		_tween.kill()

	var total_chars := dialogue_label.get_total_character_count()
	var duration := total_chars / characters_per_second
	_tween = create_tween()
	_tween.tween_property(dialogue_label, "visible_ratio", 1.0, duration)
	_tween.finished.connect(_on_typing_finished)


func set_indicator_visible(is_visible: bool) -> void:
	continue_indicator.visible = is_visible


func clear() -> void:
	if _tween and _tween.is_running():
		_tween.kill()
	dialogue_label.text = ""
	speaker_label.text = ""
	speaker_label.visible = false
	set_indicator_visible(false)


func is_showing() -> bool:
	return not dialogue_label.text.is_empty()


func _on_typing_finished() -> void:
	set_indicator_visible(true)
